PRAGMA foreign_keys=ON;
CREATE TABLE merchant_sites(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL UNIQUE REFERENCES merchants(id),name TEXT NOT NULL,theme_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_site_pages(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,site_id TEXT NOT NULL REFERENCES merchant_sites(id),slug TEXT NOT NULL,title TEXT NOT NULL,page_type TEXT NOT NULL DEFAULT 'standard',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','scheduled','published','archived')),visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN('public','hidden','token','password','member')),publish_at TEXT,unpublish_at TEXT,canonical_url TEXT,seo_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,slug),UNIQUE(merchant_id,id));
CREATE TABLE merchant_page_versions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,page_id TEXT NOT NULL,version_no INTEGER NOT NULL,content_hash TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,version_no),FOREIGN KEY(merchant_id,page_id) REFERENCES merchant_site_pages(merchant_id,id));
CREATE TABLE merchant_page_blocks(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,page_id TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES merchant_page_versions(id),block_type TEXT NOT NULL CHECK(block_type IN('hero','text','image','image_text','carousel','button','product_grid','collection_grid','video','facebook_live','map','faq','contact_form','newsletter_form','social_links','html_embed','spacer','divider','testimonials')),sort_order INTEGER NOT NULL,settings_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,page_id) REFERENCES merchant_site_pages(merchant_id,id));
CREATE TABLE merchant_navigation_menus(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,location TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,location));
CREATE TABLE merchant_navigation_items(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,menu_id TEXT NOT NULL REFERENCES merchant_navigation_menus(id),parent_id TEXT,kind TEXT NOT NULL,label TEXT NOT NULL,target TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE merchant_media_assets(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,object_key TEXT NOT NULL,mime_type TEXT NOT NULL,alt_text TEXT NOT NULL DEFAULT '',size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,object_key));
CREATE TABLE merchant_redirects(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,source_path TEXT NOT NULL,target_path TEXT NOT NULL,status_code INTEGER NOT NULL CHECK(status_code IN(301,302)),enabled INTEGER NOT NULL DEFAULT 0,UNIQUE(merchant_id,source_path));
CREATE TABLE merchant_domains(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,hostname TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_seo_settings(merchant_id TEXT PRIMARY KEY,title_template TEXT,description TEXT,robots TEXT NOT NULL DEFAULT 'noindex,nofollow',og_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE merchant_site_publications(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,page_id TEXT NOT NULL,version_id TEXT NOT NULL,published_at TEXT NOT NULL,unpublished_at TEXT,created_by TEXT NOT NULL,FOREIGN KEY(merchant_id,page_id) REFERENCES merchant_site_pages(merchant_id,id));
CREATE INDEX idx_site_pages_publish ON merchant_site_pages(merchant_id,status,publish_at,unpublish_at);
